,"text":"这里是蓉城最大的湿地公园，人气很旺，周遭居民们茶余饭后都喜欢到这里来转上两圈打发时间，渐渐成了蓉城的一处地标公园。"}]}},{"type":"record","record":{"id":"c03:B14","revision":5,"label":"苏天晴在绿心公园树林中呼吸新鲜空气，坐长椅翻阅墨丘利秘典并用手机搜索，对世界与“自己”有了新认识。","availableAt":{"chapter":3,"paragraph":58},"scope":{"world":"original","perspective":"reader"},"spans":[{"sourceId":"source-c03","sourceRevision":1,"paragraph":52,"start":0,"end":36},{"sourceId":"source-c03","sourceRevision":1,"paragraph":53,"start":0,"end":3},{"sourceId":"source-c03","sourceRevision":1,"paragraph":54,"start":0,"end":42},{"sourceId":"source-c03","sourceRevision":1,"paragraph":55,"start":0,"end":46},{"sourceId":"source-c03","sourceRevision":1,"paragraph":56,"start":0,"end":19},{"sourceId":"source-c03","sourceRevision":1,"paragraph":57,"start":0,"end":54},{"sourceId":"source-c03","sourceRevision":1,"paragraph":58,"start":0,"end":50}],"dependencies":[],"readiness":"ready","kind":"beat","data":{"gist":"苏天晴在绿心公园树林中呼吸新鲜空气，坐长椅翻阅墨丘利秘典并用手机搜索，对世界与“自己”有了新认识。","chapterId":"c03","fromParagraph":52,"toParagraph":58,"mode":"narrative","referents":[{"id":"c03:R1","revision":5},{"id":"c03:R4","revision":5},{"id":"c03:R12","revision":5},{"id":"c03:R9","revision":5}],"disclosures":[{"id":"c03:D30","revision":5}]}},"assessment":null,"assessmentStatus":"not-in-scope-or-not-applicable","provenance":{"references":[{"id":"c03:R1","revision":5,"status":"visible"},{"id":"c03:R4","revision":5,"status":"visible"},{"id":"c03:R12","revision":5,"status":"visible"},{"id":"c03:R9","revision":5,"status":"visible"},{"id":"c03:D30","revision":5,"status":"visible"}],"dependencies":[],"arguments":[],"excerpts":[{"span":{"sourceId":"source-c03","sourceRevision":1,"paragraph":52,"start":0,"end":36},"chapter":3,"text":"置身于绿意盎然的自然树林中，苏天晴不由得眯起眼睛，畅快地呼吸起新鲜空气。"},{"span":{"sourceId":"source-c03","sourceRevision":1,"paragraph":53,"start":0,"end":3},"chapter":3,"text":"愉快。"},{"span":{"sourceId":"source-c03","sourceRevision":1,"paragraph":54,"start":0,"end":42},"chapter":3,"text":"接下来做点什么好呢，这会儿也才刚过中午，包里也揣了两片面包当晚饭，要